def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp_def = 0
    for _, opp in history:
        if opp == 'D':
            opp_def += 1

    opp_def_rate = opp_def / n

    if opp_def_rate > 0.5:
        return 'D'

    if n == 99:
        return 'D'

    if n == 98:
        if opp_def_rate < 0.5:
            return 'C'
        else:
            return 'D'

    last_opp = history[-1][1]
    if last_opp == 'D':
        consec = 0
        for i in range(n - 1, -1, -1):
            if history[i][1] == 'D':
                consec += 1
            else:
                break
        if consec >= 2:
            return 'D'
        else:
            return 'C'
    else:
        return 'C'
